// Parse Claude's drafted copy and attach original sheet row data
const claudeResponse = $input.first();
const allItems = $input.all();

let contentText = '';
try {
  contentText = claudeResponse.json.content[0].text;
} catch(e) {
  return [{ json: { error: 'Claude response parse failed', raw: claudeResponse.json } }];
}

let drafts = {};
try {
  const cleaned = contentText.replace(/```json|```/g, '').trim();
  drafts = JSON.parse(cleaned);
} catch(e) {
  return [{ json: { error: 'JSON parse failed', raw: contentText } }];
}

// Retrieve the original row data from the previous node context
// We use $('Filter: Pending Outreach Only').first() via context
return [{
  json: {
    linkedinDraft: drafts.linkedinDraft || '',
    emailSubject: drafts.emailSubject || '',
    emailBody: drafts.emailBody || ''
  }
}];

// Merge the drafted copy back with the original row data
const draftsItem = $input.first();
const sheetRow = $('Filter: Pending Outreach Only').first();

return [{
  json: {
    // Original sheet fields
    'Startup Name': sheetRow.json['Startup Name'],
    'Website': sheetRow.json['Website'],
    'Funding Details': sheetRow.json['Funding Details'],
    'Founders': sheetRow.json['Founders'],
    'Source URL': sheetRow.json['Source URL'],
    'Description': sheetRow.json['Description'],
    'row_number': sheetRow.json['row_number'],
    // New drafted fields
    'LinkedIn Draft': draftsItem.json.linkedinDraft,
    'Email Draft': draftsItem.json.emailBody,
    'Email Subject': draftsItem.json.emailSubject,
    // Update status
    'Status': 'Draft Created'
  }
}];
